        static void ConfigureList(ListView l,string[] cols,int[] widths){l.Dock=DockStyle.Fill;l.View=System.Windows.Forms.View.Details;l.FullRowSelect=true;l.GridLines=false;l.HideSelection=false;l.MultiSelect=false;l.BorderStyle=BorderStyle.None;for(int i=0;i<cols.Length;i++)l.Columns.Add(cols[i],widths[i]);}
        void View(int index){selectedView=index;var controls=new Control[]{transcript,log,issues};for(int i=0;i<3;i++){views[i].Checked=i==index;controls[i].Visible=i==index;}controls[index].BringToFront();}
        void EditAction(Action<Scintilla> a){if(current!=null){current.Edit.Focus();a(current.Edit);}}
        void Indent(int mode){if(current!=null)current.Reindent(mode);}
        void Find(bool replace){if(current==null)return;if(finder!=null&&!finder.IsDisposed)finder.Close();finder=new FindDialog(()=>current,replace,current.Edit.SelectedText);finder.Show(this);}
        void ChooseBin(){if(owner!=null){Say("请先结束当前任务");return;}using(var f=new FolderBrowserDialog{Description="选择包含 g++.exe 和 gdb.exe 的 bin 目录",SelectedPath=bin??""})if(f.ShowDialog(this)==DialogResult.OK){var choice=f.SelectedPath;if(!File.Exists(Path.Combine(choice,"g++.exe"))){Error("该目录中没有 g++.exe。");return;}bin=prefs.Bin=choice;prefs.Save();Say("工具链："+bin);}}
        void NewDocument(){var used=new HashSet<int>(docs.Where(d=>d.FullPath==null).Select(d=>d.Slot));int n=1;while(used.Contains(n))n++;Insert(new SourceDocument(SourceDocument.Template,n));}
        void OpenChooser(){using(var d=new OpenFileDialog{Title="打开源文件",Filter="C++ 源文件|*.cpp;*.cc;*.cxx;*.h;*.hpp|所有文件|*.*",Multiselect=true})if(d.ShowDialog(this)==DialogResult.OK)foreach(var p in d.FileNames)OpenPath(p);}
        SourceDocument OpenPath(string path){try{path=Path.GetFullPath(path);var existing=docs.FirstOrDefault(d=>string.Equals(d.FullPath,path,StringComparison.OrdinalIgnoreCase));if(existing!=null){Activate(existing);return existing;}Encoding enc;string text=FileCodec.Read(path,out enc);var doc=new SourceDocument(text,0){FullPath=path,Encoding=enc,LastWrite=File.GetLastWriteTimeUtc(path)};Insert(doc);return doc;}catch(Exception ex){Error(ex.Message);return null;}}
        void Insert(SourceDocument d){d.Standard=current==null?prefs.Standard:current.Standard;d.O2=current==null?prefs.O2:current.O2;int index=current==null?docs.Count:docs.IndexOf(current)+1;docs.Insert(index,d);editors.Controls.Add(d.Edit);SizeEditor(d);d.Changed+=()=>{if(!closing){UpdateTab(d);if(d==current)RefreshStatus();}};d.CursorChanged+=()=>{if(d==current&&!closing)CursorStatus();};d.BreakpointChanged+=(line,on)=>Breakpoint(d,line,on);d.VariableTip=name=>VariableValue(d,name);Activate(d);}
        void Activate(SourceDocument d){if(d==null)return;current=d;foreach(var x in docs)x.Edit.Visible=x==d;d.Edit.BringToFront();d.Edit.Focus();sync=true;ShowStandard(d.Standard);optimize.Checked=d.O2;sync=false;DrawTabs();RefreshDoc();}
        void DrawTabs(){tabs.SuspendLayout();var old=tabs.Items.Cast<ToolStripItem>().ToArray();tabs.Items.Clear();foreach(var i in old)i.Dispose();foreach(var doc in docs){var t=new ToolStripButton{Image=Ui.Art("cpp-file-48"),Text=TabName(doc),DisplayStyle=ToolStripItemDisplayStyle.ImageAndText,Tag=doc,Checked=doc==current,ToolTipText=doc.FullPath??doc.Name+" · 未保存",Padding=new Padding(Px(5),0,Px(4),0),Margin=Padding.Empty};t.Click+=(s,e)=>Activate(doc);t.MouseUp+=(s,e)=>{if(e.Button==MouseButtons.Middle)CloseDoc(doc);};tabs.Items.Add(t);if(doc==current)tabs.Items.Add(Ui.Button("x","关闭文件 · Ctrl+W",()=>CloseDoc(doc)));}var plus=Ui.Button("plus","新建源文件 · Ctrl+N",NewDocument);plus.Overflow=ToolStripItemOverflow.Never;tabs.Items.Add(plus);SizeIconButtons(tabs,32,28);tabs.ResumeLayout();}
        string TabName(SourceDocument d){return d.Name.Replace("&","&&")+(d.Edit.Modified?"  •":"");}
        void UpdateTab(SourceDocument d){foreach(ToolStripItem t in tabs.Items)if(t.Tag==d)t.Text=TabName(d);}
        bool Save(SourceDocument d,bool asNew,bool forBuild){if(d==null)return false;if(d==owner){Say("请先结束当前任务");return false;}string dest=d.FullPath;bool ask=dest==null||asNew;if(!ask&&forBuild&&!d.Edit.Modified&&File.Exists(dest))return true;
            if(ask)using(var s=new SaveFileDialog{Title=forBuild?"编译前保存源文件":"保存源文件",Filter="C++ 源文件 (*.cpp)|*.cpp|所有文件|*.*",FileName=dest==null?d.Name+".cpp":Path.GetFileName(dest),DefaultExt="cpp",AddExtension=true,OverwritePrompt=true,InitialDirectory=dest==null?Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments):Path.GetDirectoryName(dest)}){if(s.ShowDialog(this)!=DialogResult.OK){d.Status=forBuild?"已取消，未开始编译":"已取消保存";RefreshStatus();return false;}dest=s.FileName;}
            return WriteDocument(d,dest);}
        bool WriteDocument(SourceDocument d,string dest){try{dest=Path.GetFullPath(dest);if(docs.Any(other=>other!=d&&string.Equals(other.FullPath,dest,StringComparison.OrdinalIgnoreCase))){Error("文件已经在另一个标签中打开。");return false;}if(dest==d.FullPath&&File.Exists(dest)&&File.GetLastWriteTimeUtc(dest)!=d.LastWrite&&MessageBox.Show(this,"文件已被其他程序修改。覆盖磁盘上的版本？","文件已更改",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return false;
                FileCodec.Write(dest,d.Edit.Text,d.Encoding);if(!string.Equals(dest,d.FullPath,StringComparison.OrdinalIgnoreCase)){d.RunText=d.LogText="";d.Problems.Clear();d.BuildFailed=false;d.BuiltSource=null;}d.FullPath=dest;d.Slot=0;d.LastWrite=File.GetLastWriteTimeUtc(dest);d.Edit.SetSavePoint();d.Status="已保存";DrawTabs();RefreshDoc();return true;}catch(Exception ex){Error("保存失败："+ex.Message);return false;}}
        bool CanClose(SourceDocument d){if(!d.Edit.Modified)return true;Activate(d);var r=MessageBox.Show(this,"保存对「"+d.Name+"」的修改？","关闭源文件",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);return r==DialogResult.No||r==DialogResult.Yes&&Save(d,false,false);}
        void CloseDoc(SourceDocument d){if(d==null)return;if(owner==d){Say("请先停止当前任务");return;}if(!CanClose(d))return;int at=docs.IndexOf(d);docs.Remove(d);editors.Controls.Remove(d.Edit);current=null;d.Dispose();if(docs.Count==0)NewDocument();else Activate(docs[Math.Min(at,docs.Count-1)]);}
        void RefreshDoc(){if(current==null)return;log.Text=current.LogText;transcript.Text=current.RunText;RenderIssues(current.Problems);views[2].Text="问题"+(current.Problems.Count>0?" ("+current.Problems.Count+")":"");RefreshStatus();}
        void RefreshStatus(){if(current==null)return;Text=current.Name+(current.Edit.Modified?" *":"")+" - Mini C++";status.Text=current.Status+(current.FullPath==null?"  ·  未保存":"");encoding.Text=(current.Encoding.CodePage==65001?"UTF-8":current.Encoding.WebName)+"  "+current.Edit.EolMode.ToString().ToUpperInvariant();CursorStatus();}
        void CursorStatus(){if(current==null)return;var e=current.Edit;position.Text="行 "+(e.CurrentLine+1)+"，列 "+(e.GetColumn(e.CurrentPosition)+1);}
        void Say(string text){if(current!=null){current.Status=text;RefreshStatus();}}
        void Error(string text){if(!closing)MessageBox.Show(this,text,"Mini C++",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
        void JumpIssue(bool hint){int index=issueStarts.BinarySearch(issues.SelectionStart);if(index<0)index=~index-1;if(index<0||shownIssues==null||index>=shownIssues.Count)return;var d=shownIssues[index];if(d.Line<1||!File.Exists(d.File))return;var doc=OpenPath(d.File);if(doc!=null){doc.Location(hint&&d.HintLine>0?d.HintLine:d.Line,hint&&d.HintColumn>0?d.HintColumn:d.Column);doc.Edit.Focus();}}
        protected override bool ProcessCmdKey(ref Message msg,Keys key){if(current!=null&&current.Edit.ContainsFocus){if(key==(Keys.Control|Keys.Tab)){Indent(0);return true;}if(key==Keys.Tab||key==(Keys.Shift|Keys.Tab)){Indent(key==Keys.Tab?1:-1);return true;}}return base.ProcessCmdKey(ref msg,key);}
        void OnClosing(object sender,FormClosingEventArgs e){if(owner!=null){if(MessageBox.Show(this,"结束当前任务并退出？","Mini C++",MessageBoxButtons.YesNo)!=DialogResult.Yes){e.Cancel=true;return;}Stop();}foreach(var d in docs.ToArray())if(!CanClose(d)){e.Cancel=true;return;}closing=true;sampler.Stop();if(jobToken!=null)jobToken.Cancel();if(debug!=null)debug.Dispose();prefs.Save();}
        protected override void Dispose(bool disposing){if(disposing)sampler.Dispose();base.Dispose(disposing);}
    }
